  const RETAINED_FOOT = [-34.44068145751953, 51.08897476196289, 9.768296241760254];
  const RETAINED_WITNESS = [-34, 51.05, 10];
  const occCentre = occupancyRequirementVerdict({ samples: [{ witnessOccupied: true }],
    standPoint: RETAINED_CENTRE, standPointFrame: 'bodyCentre', witnessPose: RETAINED_WITNESS });
  ok(occCentre.ok === false && occCentre.problems.some((x) => /UNMEASURED/.test(x)),
    'OLD-MISMATCH: a body-CENTRE stand point is refused as an unmeasured frame, not silently scored');
  const occFoot = occupancyRequirementVerdict({ samples: [{ witnessOccupied: true }],
    standPoint: RETAINED_FOOT, standPointFrame: 'foot', witnessPose: RETAINED_WITNESS });
  ok(occFoot.ok === true && occFoot.insideOccupancy === true,
    'NEW-EQUIVALENT: the runtime-published FOOT pose for the same retained instant is inside the 1.25/0.6 cylinder');
  ok(occupancyRequirementVerdict({ samples: [{ witnessOccupied: true }],
    standPoint: [RETAINED_FOOT[0], RETAINED_FOOT[1] + 0.7, RETAINED_FOOT[2]], standPointFrame: 'foot', witnessPose: RETAINED_WITNESS }).insideOccupancy === false,
    'the 0.6 VERTICAL allowance is unchanged: a foot pose 0.74u high still fails');
  ok(occupancyRequirementVerdict({ samples: [{ witnessOccupied: true }],
    standPoint: [-34, 51.05, 11.3], standPointFrame: 'foot', witnessPose: RETAINED_WITNESS }).insideOccupancy === false,
